      }
      // Sem sinal: mantém os níveis do sinal anterior (comportamento padrão)

      // ===== Setas indicadoras dos níveis de TP e SL =====
      if (compra)
         TPArrowBuffer[i] = entrada + Tppoints * _Point;            // seta ↑ apontando pro alvo
      else if (venda)
         SLArrowBuffer[i] = entrada - Tppoints * _Point;            // seta ↓ apontando pro alvo

